using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using PiperPlus.Core.Mapping;

namespace PiperPlus.Core.Phonemize;

/// <summary>
/// Chinese G2P engine driven by the shared numeric-tone pinyin dictionaries
/// (<c>pinyin_single.json</c> / <c>pinyin_phrases.json</c>, generated by
/// <c>scripts/build_pinyin_dicts.py</c>). Port of the Go
/// <c>phonemize.ChinesePhonemizer</c>, so the output matches Python, Rust,
/// Go, C++ and the browser token for token
/// (<c>tests/fixtures/g2p/phoneme_test_cases_golden.json</c>).
/// <para>
/// Pipeline: longest phrase match (2-8 characters) falling back to the
/// first single-character reading, tone sandhi per run of Chinese
/// characters, pinyin to IPA via <see cref="PinyinToIpa"/>, erhua, and
/// multi-character IPA to PUA codepoints.
/// </para>
/// </summary>
public sealed class PinyinDictionaryChineseG2PEngine : IChineseG2PEngine
{
    private const int MaxPhraseLength = 8;

    // Fullwidth punctuation -> ASCII, matching every other runtime.
    private static readonly Dictionary<char, char> PunctuationMap = new()
    {
        ['。'] = '.',
        ['，'] = ',',
        ['！'] = '!',
        ['？'] = '?',
        ['、'] = ',',
        ['；'] = ';',
        ['：'] = ':',
        ['…'] = '.',
        ['—'] = ',',
        ['“'] = '"',
        ['”'] = '"',
        ['‘'] = '\'',
        ['’'] = '\'',
    };

    private static readonly HashSet<char> AsciiPunctuation = [',', '.', ';', ':', '!', '?'];

    private readonly IReadOnlyDictionary<int, string> _single;
    private readonly IReadOnlyDictionary<string, string[]> _phrases;

    /// <summary>
    /// Initializes a new instance of the <see cref="PinyinDictionaryChineseG2PEngine"/> class.
    /// </summary>
    /// <param name="single">
    /// Codepoint to comma-separated numeric-tone readings (first one is used).
    /// </param>
    /// <param name="phrases">Phrase to one numeric-tone syllable per character.</param>
    public PinyinDictionaryChineseG2PEngine(
        IReadOnlyDictionary<int, string> single,
        IReadOnlyDictionary<string, string[]> phrases)
    {
        _single = single ?? throw new ArgumentNullException(nameof(single));
        _phrases = phrases ?? throw new ArgumentNullException(nameof(phrases));
    }

    /// <summary>
    /// Load the dictionaries from their JSON form: <c>{"20320": "ni3"}</c> and
    /// <c>{"你好": [["ni3"], ["hao3"]]}</c>.
    /// </summary>
    /// <param name="single">Stream of <c>pinyin_single.json</c>.</param>
    /// <param name="phrases">Stream of <c>pinyin_phrases.json</c>.</param>
    /// <returns>The engine.</returns>
    public static PinyinDictionaryChineseG2PEngine FromJson(Stream single, Stream phrases)
    {
        ArgumentNullException.ThrowIfNull(single);
        ArgumentNullException.ThrowIfNull(phrases);

        var singleDict = new Dictionary<int, string>();
        using (JsonDocument doc = JsonDocument.Parse(single))
        {
            IEnumerable<JsonProperty> entries = doc.RootElement.EnumerateObject()
                .Where(e => e.Value.ValueKind == JsonValueKind.String && int.TryParse(e.Name, out _));
            foreach (JsonProperty entry in entries)
            {
                singleDict[int.Parse(entry.Name)] = entry.Value.GetString()!;
            }
        }

        var phraseDict = new Dictionary<string, string[]>();
        using (JsonDocument doc = JsonDocument.Parse(phrases))
        {
            foreach (JsonProperty entry in doc.RootElement.EnumerateObject())
            {
                // First reading of each character; characters with no reading are skipped.
                phraseDict[entry.Name] = entry.Value.EnumerateArray()
                    .Where(alternatives => alternatives.GetArrayLength() > 0
                        && alternatives[0].ValueKind == JsonValueKind.String)
                    .Select(alternatives => alternatives[0].GetString()!)
                    .ToArray();
            }
        }

        return new PinyinDictionaryChineseG2PEngine(singleDict, phraseDict);
    }

    /// <inheritdoc />
    public ChineseG2PResult Convert(string text)
    {
        ArgumentNullException.ThrowIfNull(text);

        int[] codepoints = ToCodepoints(text);
        var (syllableIndex, wordLength) = BuildWordInfo(codepoints);
        CharPinyin?[] readings = TextToPinyin(codepoints);
        ApplyToneSandhi(readings);

        var tokens = new List<string>();
        var a1 = new List<int>();
        var a2 = new List<int>();
        var a3 = new List<int>();

        void Add(string token, int tone, int position, int length)
        {
            tokens.Add(token);
            a1.Add(tone);
            a2.Add(position);
            a3.Add(length);
        }

        for (int i = 0; i < codepoints.Length; i++)
        {
            int cp = codepoints[i];
            if (readings[i] is not { } reading)
            {
                string ch = char.ConvertFromUtf32(cp);
                if (cp <= char.MaxValue && PunctuationMap.TryGetValue((char)cp, out char mapped))
                {
                    Add(mapped.ToString(), 0, 0, 0);
                }
                else if (cp <= char.MaxValue && (AsciiPunctuation.Contains((char)cp) || PunctuationMap.ContainsKey((char)cp)))
                {
                    Add(ch, 0, 0, 0);
                }
                else if (Rune.IsWhiteSpace(new Rune(cp)))
                {
                    Add(" ", 0, 0, 0);
                }
                else if (Rune.IsDigit(new Rune(cp)) || Rune.IsLetter(new Rune(cp)))
                {
                    Add(ch, 0, 0, 1);
                }

                continue;
            }

            string syllable = reading.Syllable;
            bool erhua = syllable.Length > 1 && syllable != "er" && syllable.EndsWith('r');
            if (erhua)
            {
                syllable = syllable[..^1];
            }

            List<string> ipa = PinyinToIpa.Convert(syllable, reading.Tone);
            if (erhua)
            {
                bool endsWithTone = ipa.Count > 0 && ipa[^1].StartsWith("tone", StringComparison.Ordinal);
                ipa.Insert(endsWithTone ? ipa.Count - 1 : ipa.Count, "ɚ");
            }

            foreach (string token in ipa)
            {
                Add(token, reading.Tone, syllableIndex[i], wordLength[i]);
            }
        }

        return new ChineseG2PResult(OpenJTalkToPiperMapping.MapSequence(tokens), a1, a2, a3);
    }

    private static bool IsCjk(int cp) => cp is (>= 0x4E00 and <= 0x9FFF) or (>= 0x3400 and <= 0x4DBF);

    private static int[] ToCodepoints(string text)
    {
        var codepoints = new List<int>(text.Length);
        foreach (Rune rune in text.EnumerateRunes())
        {
            codepoints.Add(rune.Value);
        }

        return [.. codepoints];
    }

    // A2 (1-based position) and A3 (length) of each character inside its run
    // of consecutive CJK characters; 1/1 for characters outside a run.
    private static (int[] Position, int[] Length) BuildWordInfo(int[] codepoints)
    {
        var position = new int[codepoints.Length];
        var length = new int[codepoints.Length];
        Array.Fill(position, 1);
        Array.Fill(length, 1);
        int start = 0;
        while (start < codepoints.Length)
        {
            if (!IsCjk(codepoints[start]))
            {
                start++;
                continue;
            }

            int end = start;
            while (end < codepoints.Length && IsCjk(codepoints[end]))
            {
                end++;
            }

            for (int i = start; i < end; i++)
            {
                position[i] = i - start + 1;
                length[i] = end - start;
            }

            start = end;
        }

        return (position, length);
    }

    private CharPinyin?[] TextToPinyin(int[] codepoints)
    {
        var readings = new CharPinyin?[codepoints.Length];
        int i = 0;
        while (i < codepoints.Length)
        {
            if (!IsCjk(codepoints[i]))
            {
                i++;
                continue;
            }

            if (TryMatchPhrase(codepoints, i, out int matchLength, out string[] syllables))
            {
                for (int j = 0; j < matchLength; j++)
                {
                    (string baseSyllable, int tone) = j < syllables.Length
                        ? PinyinToIpa.ExtractTone(syllables[j])
                        : (string.Empty, 5);
                    readings[i + j] = new CharPinyin(PinyinToIpa.NormalizePinyin(baseSyllable), tone);
                }

                i += matchLength;
                continue;
            }

            if (_single.TryGetValue(codepoints[i], out string? raw))
            {
                int comma = raw.IndexOf(',', StringComparison.Ordinal);
                (string baseSyllable, int tone) = PinyinToIpa.ExtractTone(comma >= 0 ? raw[..comma] : raw);
                readings[i] = new CharPinyin(PinyinToIpa.NormalizePinyin(baseSyllable), tone);
            }

            i++;
        }

        return readings;
    }

    private bool TryMatchPhrase(int[] codepoints, int start, out int length, out string[] syllables)
    {
        int maxLength = Math.Min(codepoints.Length - start, MaxPhraseLength);
        var key = new StringBuilder();
        for (length = maxLength; length >= 2; length--)
        {
            key.Clear();
            for (int k = start; k < start + length; k++)
            {
                key.Append(char.ConvertFromUtf32(codepoints[k]));
            }

            if (_phrases.TryGetValue(key.ToString(), out string[]? found))
            {
                syllables = found;
                return true;
            }
        }

        length = 0;
        syllables = [];
        return false;
    }

    // Sandhi runs over each group of consecutive characters that have a
    // reading; an unknown character or punctuation ends the group.
    private static void ApplyToneSandhi(CharPinyin?[] readings)
    {
        int i = 0;
        while (i < readings.Length)
        {
            if (readings[i] is null)
            {
                i++;
                continue;
            }

            int start = i;
            while (i < readings.Length && readings[i] is not null)
            {
                i++;
            }

            if (i - start < 2)
            {
                continue;
            }

            var group = new List<(string Syllable, int Tone)>(i - start);
            for (int j = start; j < i; j++)
            {
                group.Add((readings[j]!.Syllable, readings[j]!.Tone));
            }

            PinyinToIpa.ApplyToneSandhi(group);
            for (int j = start; j < i; j++)
            {
                readings[j] = readings[j]! with { Tone = group[j - start].Tone };
            }
        }
    }

    private sealed record CharPinyin(string Syllable, int Tone);
}
